FORMATS = {'list', 'bullet', 'bullets', 'table', 'summary', 'paragraph', 'sentence', 'sentences', 'steps', 'email'}


def prompt_check(prompt):
    words = prompt.split()
    clean = [w.strip('.,!?:;').lower() for w in words]
    has_format = any(w in FORMATS for w in clean)
    lower = prompt.lower()
    idx = lower.find(' for ')
    has_audience = idx != -1 and lower[idx + 5:].strip() != ''
    verdict = 'SPECIFIC' if len(words) >= 8 and has_format and has_audience else 'VAGUE'
    return {'words': len(words), 'has_format': has_format, 'has_audience': has_audience, 'verdict': verdict}

def build_prompt(topic, fmt, audience):
