ORDER = ['context', 'role', 'instructions', 'actions', 'tone', 'examples']


def create_prompt(parts):
    lines, missing = [], []
    for key in ORDER:
        value = (parts.get(key) or '').strip()
        if value:
            lines.append(f'{key.capitalize()}: {value}')
        else:
            missing.append(key)
    return {'prompt': '\n'.join(lines), 'missing': missing, 'complete': not missing}

def few_shot_prompt(instruction, examples, query):
    blocks = [instruction] + [f'Input: {i}\nOutput: {o}' for i, o in examples] + [f'Input: {query}\nOutput:']
    n = len(examples)
    kind = 'ZERO_SHOT' if n == 0 else 'ONE_SHOT' if n == 1 else 'FEW_SHOT'
    return {'prompt': '\n\n'.join(blocks), 'kind': kind}

def _words(text):
    return {w.strip('.,!?').lower() for w in text.split()} - {''}


def pick_examples(pool, query, k):
    q = _words(query)
    ranked = sorted(enumerate(pool), key=lambda p: (-len(_words(p[1][0]) & q), p[0]))
    return [pair for _, pair in ranked[:k]]

def self_consistency(answers):
    if not answers:
        raise ValueError('no answers')
    norm = [a.strip().lower() for a in answers]
    best = max(dict.fromkeys(norm), key=norm.count)
    votes = norm.count(best)
    pct = round(votes / len(norm) * 100, 1)
    return {'answer': best, 'votes': votes, 'consensus_pct': pct, 'reliable': pct >= 60}

