def prompt_budget(system, user, max_context, reserve_output):
    s = math.ceil(len(system) / 4)
    u = math.ceil(len(user) / 4)
    total = s + u
    return {'system_tokens': s, 'user_tokens': u, 'total': total,
            'fits': total + reserve_output <= max_context, 'remaining': max_context - total - reserve_output}

def api_cost(calls, in_tokens, out_tokens, in_per_million, out_per_million):
    per_call = in_tokens / 1e6 * in_per_million + out_tokens / 1e6 * out_per_million
    total = per_call * calls
    return {'per_call': round(per_call, 6), 'total': round(total, 4), 'monthly_30d': round(total * 30, 2)}

import math


def apply_temperature(logits, temperature):
    if temperature < 0:
        raise ValueError('temperature must be >= 0')
    if temperature == 0:
        best = max(logits, key=logits.get)
        return {k: (1.0 if k == best else 0.0) for k in logits}
    top = max(logits.values())
    exps = {k: math.exp((v - top) / temperature) for k, v in logits.items()}
    total = sum(exps.values())
    return {k: round(e / total, 4) for k, e in exps.items()}

def top_p_filter(probs, p):
    ranked = sorted(probs.items(), key=lambda kv: (-kv[1], kv[0]))
    kept, cum = [], 0.0
    for token, prob in ranked:
        kept.append((token, prob))
        cum += prob
        if cum >= p - 1e-9:
            break
    total = sum(prob for _, prob in kept)
    return {token: round(prob / total, 4) for token, prob in kept}

