from collections import Counter

STOP = {'the', 'a', 'an', 'and', 'of', 'to', 'in', 'is', 'it', 'for', 'on', 'was', 'with', 'as', 'are', 'this', 'that'}


def extractive_summary(text, n):
    sentences = re.split(r'(?<=[.!?])\s+', text.strip())
    freq = Counter(w for w in re.findall(r'[a-z]+', text.lower()) if w not in STOP)
    scores = [sum(freq[w] for w in re.findall(r'[a-z]+', s.lower()) if w not in STOP) for s in sentences]
    top = sorted(range(len(sentences)), key=lambda i: (-scores[i], i))[:n]
    return ' '.join(sentences[i] for i in sorted(top))

def compression_check(original, summary):
    total = len(original.split())
    if total == 0:
        raise ValueError('original is empty')
    ratio = round(len(summary.split()) / total, 3)
    verdict = 'TOO_LONG' if ratio > 0.5 else 'TOO_SHORT' if ratio < 0.1 else 'OK'
    return {'ratio': ratio, 'verdict': verdict}

