def retrieve(chunks, query, k):
    q = _words(query)
    scored = [(len(q & _words(c)), i) for i, c in enumerate(chunks)]
    ranked = sorted((s for s in scored if s[0] > 0), key=lambda s: (-s[0], s[1]))
    return [i for _, i in ranked[:k]]

