def check_citations(answer, n_sources):
    nums = {int(x) for x in re.findall(r'\[(\d+)\]', answer)}
    cited = sorted(n for n in nums if 1 <= n <= n_sources)
    invalid = sorted(n for n in nums if not 1 <= n <= n_sources)
