def cross_check(claims_by_source):
    counts = {}
    for claims in claims_by_source.values():
        for claim in {c.strip().lower() for c in claims}:
            counts[claim] = counts.get(claim, 0) + 1
    return {'confirmed': sorted(c for c, n in counts.items() if n >= 2),
            'single_source': sorted(c for c, n in counts.items() if n == 1)}

def run_chain(steps, text):
    current, trace = text, []
    for name, fn in steps:
        result = fn(current)
        trace.append((name, len(result)))
        if not result.strip():
            return {'output': current, 'trace': trace, 'failed': name}
        current = result
    return {'output': current, 'trace': trace, 'failed': None}

CASUAL = {'hey', 'gonna', 'wanna', 'cool', 'awesome', 'stuff', 'kinda', 'yeah', 'lol', 'guys'}


def formality(text):
    words = text.split()
    hits = sum(1 for w in words if "'" in w)
    hits += sum(1 for w in words if w.strip('.,!?').lower() in CASUAL)
    hits += text.count('!')
    score = max(0, 100 - 10 * hits)
    label = 'FORMAL' if score >= 80 else 'NEUTRAL' if score >= 50 else 'CASUAL'
    return {'score': score, 'label': label}

def memo(to, sender, subject, points):
    clean = [p.strip() for p in points if p.strip()]
    if not clean:
        raise ValueError('a memo needs at least one point')
    lines = [f'TO: {to}', f'FROM: {sender}', f'SUBJECT: {subject}', '']
    lines += [f'{i}. {p}' for i, p in enumerate(clean, 1)]
    return '\n'.join(lines)

import re


def dedupe_ideas(ideas):
    seen, out = set(), []
    for idea in ideas:
        key = frozenset(re.sub(r'[^a-z0-9 ]', ' ', idea.lower()).split())
        if key not in seen:
            seen.add(key)
            out.append(idea.strip())
    return out

