def grounded_prompt(question, chunks, k=2):
    q = _words(question)
    scored = sorted(((len(q & _words(c)), i) for i, c in enumerate(chunks)), key=lambda s: (-s[0], s[1]))
    ids = [i for s, i in scored if s > 0][:k]
    lines = [f'[{n}] {chunks[i]}' for n, i in enumerate(ids, 1)]
