import ast


def review(source):
    try:
        tree = ast.parse(source)
    except SyntaxError:
        raise ValueError('code does not parse')
    issues = []
    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            if ast.get_docstring(node) is None:
                issues.append(f'no docstring: {node.name}')
            defaults = node.args.defaults + [d for d in node.args.kw_defaults if d is not None]
            if any(isinstance(d, (ast.List, ast.Dict, ast.Set)) for d in defaults):
                issues.append(f'mutable default: {node.name}')
        elif isinstance(node, ast.ExceptHandler) and node.type is None:
            issues.append('bare except')
    return sorted(issues)

