import re


def run_agent(model_outputs, tools, max_steps):
    observations = []
    for line in model_outputs[:max_steps]:
        stripped = line.strip()
        if stripped.lower().startswith('final answer:'):
            return {'answer': stripped[len('final answer:'):].strip(), 'observations': observations}
        m = re.match(r'action:\s*(\w+)\s*\[(.*)\]$', stripped, re.IGNORECASE)
        if m:
            tool, arg = m.group(1), m.group(2).strip()
            if tool in tools:
                observations.append(str(tools[tool](arg)))
            else:
                observations.append(f'unknown tool: {tool}')
    return {'answer': None, 'observations': observations}

def route_event(event, rules):
    actions = []
    for rule in rules:
        if rule['field'] in event and event[rule['field']] == rule['equals'] and rule['action'] not in actions:
            actions.append(rule['action'])
    return actions or ['log_only']

def backoff(attempts, base, cap):
    if attempts < 0 or base <= 0:
        raise ValueError('attempts must be >= 0 and base > 0')
    return [min(cap, base * 2 ** i) for i in range(attempts)]

