FALLBACK = "I don't know. Please contact support."


def _words(text):
    return set(re.findall(r'[a-z0-9]+', text.lower()))


def faq_answer(question, faq, threshold=0.3):
    q = _words(question)
    best, best_score = None, -1.0
    for faq_q, faq_a in faq:
        f = _words(faq_q)
        score = len(q & f) / len(q | f) if q | f else 0.0
        if score > best_score:
            best, best_score = faq_a, score
    score = round(max(best_score, 0.0), 3)
    if best is None or best_score < threshold:
        return {'answer': FALLBACK, 'score': score}
    return {'answer': best, 'score': score}

