RISKY = ['indemnify', 'unlimited liability', 'auto-renew', 'penalty', 'non-compete']


def risky_clauses(contract):
    found = []
    for line in contract.splitlines():
        m = re.match(r'\s*(\d+)\.\s*(.*)', line)
        if not m:
            continue
        low = m.group(2).lower()
        terms = sorted(t for t in RISKY if t in low)
        if terms:
            found.append((int(m.group(1)), terms))
    return found

def leaderboard(results):
    rows = [(m, round(sum(r) / len(r) * 100, 1)) for m, r in results.items() if r]
