def win_rates(judgements):
    points, games = {}, {}
    for a, b, winner in judgements:
        for m in (a, b):
            games[m] = games.get(m, 0) + 1
            points[m] = points.get(m, 0) + (1 if winner == m else 0.5 if winner == 'tie' else 0)
    return {m: round(points[m] / games[m], 3) for m in sorted(games)}

def fits_on_gpu(params_billion, bits, vram_gb, overhead=1.2):
    if bits not in (4, 8, 16, 32):
        raise ValueError('bits must be 4, 8, 16 or 32')
    needed = round(params_billion * bits / 8 * overhead, 2)
    return {'needed_gb': needed, 'fits': needed <= vram_gb}

def choose_bits(params_billion, vram_gb, overhead=1.2):
    for bits in (16, 8, 4):
        if params_billion * bits / 8 * overhead <= vram_gb:
            return bits
    return None

PHRASES = ['ignore previous instructions', 'ignore all previous', 'you are now',
           'system prompt', 'developer mode', 'disregard your']
FORMATS = {'list', 'bullet', 'bullets', 'table', 'summary', 'steps', 'json', 'email', 'paragraph'}


def lint_prompt(prompt):
    low = prompt.lower()
    words = [w.strip('.,!?:;') for w in low.split()]
    checks = {
        'role': 'you are' in low,
        'format': any(w in FORMATS for w in words),
        'audience': ' for ' in low,
        'example': 'example' in low or 'input:' in low,
        'length': len(prompt.split()) >= 12,
    }
    score = 20 * sum(checks.values())
    issues = [name for name, ok in checks.items() if not ok]
    if any(p in low for p in PHRASES):
        score -= 40
        issues.append('injection')
    return {'score': max(0, score), 'issues': sorted(issues)}

def certificate_ready(scores, min_avg=70, min_each=50):
    avg = round(sum(scores.values()) / len(scores), 1) if scores else 0.0
    weak = sorted(d for d, s in scores.items() if s < min_each)
    return {'average': avg, 'weak_days': weak, 'ready': bool(scores) and avg >= min_avg and not weak}
